INSERT INTO changelog (title, body, created_at) VALUES
('Живий текст під час диктування',
'Коли диктуєш (чат Джері, будь-яке поле з мікрофоном, затиснутий робот) — текст зʼявляється в полі одразу, поки говориш, як у Claude. Працює через ElevenLabs Realtime (Scribe v2 Realtime); на «стоп» дописується останній шматок. Якщо живе розпізнавання не підключилось — працює як раніше (текст після «стоп»). Вимикається: Налаштування → «Можливості» → «Живий текст під час диктування».',
'2026-10-31 10:00:00');
